package com.akira.one;
import android.app.*;import android.content.*;import android.net.Uri;import android.os.*;import androidx.core.content.FileProvider;import org.json.JSONObject;import java.io.File;
public final class UpdateManager{private UpdateManager(){}public static void check(Activity a,JSONObject u){int code=u.optInt("version_code",0);String url=u.optString("apk_url","");if(code<=AppVersion.code(a)||url.isBlank())return;String msg=u.optString("message","Há uma nova versão da Akira TV disponível.");new androidx.appcompat.app.AlertDialog.Builder(a).setTitle("Atualização disponível").setMessage(msg).setPositiveButton("Baixar e instalar",(d,w)->download(a,url,code)).setNegativeButton("Depois",null).show();}
 private static void download(Activity a,String url,int code){DownloadManager dm=(DownloadManager)a.getSystemService(Context.DOWNLOAD_SERVICE);String name="akira-tv-"+code+".apk";DownloadManager.Request r=new DownloadManager.Request(Uri.parse(url));r.setTitle("Atualizando Akira TV");r.setDescription("Baixando nova versão");r.setNotificationVisibility(DownloadManager.Request.VISIBILITY_VISIBLE_NOTIFY_COMPLETED);r.setDestinationInExternalFilesDir(a,Environment.DIRECTORY_DOWNLOADS,name);long id=dm.enqueue(r);android.widget.Toast.makeText(a,"Download iniciado",android.widget.Toast.LENGTH_SHORT).show();BroadcastReceiver br=new BroadcastReceiver(){public void onReceive(Context c,Intent i){if(i.getLongExtra(DownloadManager.EXTRA_DOWNLOAD_ID,-1)!=id)return;try{a.unregisterReceiver(this);}catch(Exception ignored){}File f=new File(a.getExternalFilesDir(Environment.DIRECTORY_DOWNLOADS),name);if(!f.exists())return;Uri uri=FileProvider.getUriForFile(a,a.getPackageName()+".fileprovider",f);Intent install=new Intent(Intent.ACTION_VIEW);install.setDataAndType(uri,"application/vnd.android.package-archive");install.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION|Intent.FLAG_ACTIVITY_NEW_TASK);a.startActivity(install);}};IntentFilter filter=new IntentFilter(DownloadManager.ACTION_DOWNLOAD_COMPLETE);if(Build.VERSION.SDK_INT>=33)a.registerReceiver(br,filter,Context.RECEIVER_NOT_EXPORTED);else a.registerReceiver(br,filter);}}
